for q in queries:
    resp = httpx.get("https://api.semanticscholar.org/graph/v1/paper/search", params={
        "query": q, "limit": 20, "fields": "title,authors,year,abstract,externalIds,url,citationCount"
    })
    if resp.status_code == 200:
        data = resp.json()
        for p in data.get("data", []):
            pid = p.get("paperId")
            if pid and pid not in all_papers:
                all_papers[pid] = p

