import httpx, json, time

# Search one at a time with delays to avoid rate limiting
queries = [
    "locating editing factual associations GPT",
    "causal scrubbing algorithm evaluating mechanistic",
    "attribution patching activation patching transformer",
    "toward monosemanticity decomposing language models",
    "interpretability in the wild indirect object identification",
]

for q in queries:
    try:
        resp = httpx.get("https://api.semanticscholar.org/graph/v1/paper/search", params={
            "query": q, "limit": 3, "fields": "title,authors,year,externalIds,citationCount"
        }, timeout=30)
        if resp.status_code == 200:
            data = resp.json()
            for p in data.get("data", []):
                authors = ", ".join([a["name"] for a in (p.get("authors") or [])[:3]])
                ext = p.get("externalIds", {}) or {}
                arxiv = ext.get("ArXiv", "")
